from pathlib import Path
from kernel_agent.cdi_qualification import DATA,ENVIRONMENT,PROFILE,RUNTIME_FILES,SCOPE,TARGET
ROOT=Path(__file__).resolve().parents[2]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 paths={'stability':'evidence/20261124-3060-next-qualification/verification.json','preview':'evidence/20261124-3060-0.1.3rc2-installed/verification.json','independent':'evidence/20261124-3060-next-independent/verification.json','qualified_install':'evidence/20261124-3060-0.1.3-installed/verification.json','active_entry':'evidence/20261124-3060-active-entry/verification.json','runtime_backup':'evidence/20261124-3060-runtime-image-backup/result.json','application_backup':'evidence/20261124-3060-application-backup/result.json','postflight':'evidence/20261124-3060-final-postflight/result.json','package_integrity':'evidence/20261124-3060-final-package-review/result.json','ga_pid_supplement':'evidence/20261124-3060-ga-pid-supplement/verification.json'};values={k:json.loads((ROOT/p).read_text()) for k,p in paths.items()};s=values['stability'];assert s['status']=='AUDIT_PASS_STABILITY_PASS' and s['aa_sessions']==s['ab_sessions']==3 and s['raw_segments']==1728;assert values['preview']['status']=='AUDIT_PASS_PREVIEW' and values['independent']['status']=='AUDIT_PASS' and values['independent']['checked_outputs']==16;assert values['qualified_install']['status']=='AUDIT_PASS_QUALIFIED_INSTALL' and values['qualified_install']['actual_package_rollback_pass'];assert values['active_entry']['status']=='AUDIT_PASS_ACTIVE_ENTRY' and values['active_entry']['actual_package_switch_pass'];backup=values['runtime_backup'];assert backup['status']=='IMAGE_BACKUP_SHA_CONFIG_AND_ALL_LAYER_DIFFIDS_PASS' and backup['image_id']==ENVIRONMENT['image_id'] and backup['remote_restore_test']['docker_load_exit']==0
 application=values['application_backup'];assert application['status']=='APPLICATION_BACKUP_ALL_MEMBERS_SHA_AND_MODE_PASS' and sha(application['archive'])==application['archive_sha256'] and application['private_data_included'] is False
 postflight=values['postflight'];assert postflight['status']=='PRODUCTION_ENTRY_QUALIFIED_IDLE_AND_RESTORED_PASS' and postflight['no_owned_containers'] and postflight['power_limit_watts']==170 and postflight['local_private_permissions_pass']
 assert values['package_integrity']['status']=='GA_RC2_RUNTIME_AND_BINARY_BYTE_IDENTITY_PASS' and values['ga_pid_supplement']['status']=='AUDIT_PASS_ACTUAL_HOST_PID_SUPPLEMENT' and values['ga_pid_supplement']['actual_native_host_pid_verified']
 wheel=ROOT/'artifacts/wheels/nvidia_kernel_agent-0.1.3-py3-none-any.whl';assert sha(wheel)==values['qualified_install']['wheel_sha256'];cert=DATA/'gemm_qualification.json';c=json.loads(cert.read_text());assert c['scope']==SCOPE and c['production_release'] is True and c['target_binding']==TARGET and c['environment']==ENVIRONMENT and all(sha(ROOT/n)==h for n,h in c['runtime_files'].items());active=json.loads((ROOT/'evidence/20261124-3060-active-entry/result.json').read_text());out=ROOT/'releases/rtx3060-gemm-v0.1.3';out.mkdir(exist_ok=False)
 manifest={'schema_version':1,'version':'0.1.3','scope':SCOPE,'backend':'cublas','production_release':True,'source_execution_enabled':False,'target_binding':TARGET,'environment':ENVIRONMENT,'operating_profile':PROFILE,'wheel':str(wheel.relative_to(ROOT)),'wheel_sha256':sha(wheel),'qualification_sha256':sha(cert),'runtime_files':{n:sha(ROOT/n) for n in RUNTIME_FILES},'deployment':{k:active[k] for k in ['root','launcher','package_switcher','store','workspace','current_prefix']},'evidence':{p:sha(ROOT/p) for p in paths.values()},'runtime_backup':backup,'application_backup':application,'stability':{k:s[k] for k in ['max_aa_pair_deviation','max_aa_group_deviation','minimum_nonregression_geomean','aa_sessions','ab_sessions','raw_segments']},'independent_outputs':16,'known_scope_limits':['fixed reviewed cuBLAS only; no arbitrary model source','only this GPU UUID/driver/image/profile','no optimization gain or single-request tail-latency claim','Attention/MLA production remains on3070'],'old_rejections_retained':True,'old_heldout_rerun':False,'new_cuda_compilation':False,'new_model_calls':0};(out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print(json.dumps({'status':'FORMAL_3060_GEMM_RELEASE_PUBLISHED','manifest':str(out/'manifest.json'),'wheel_sha256':manifest['wheel_sha256'],'qualification_sha256':manifest['qualification_sha256'],'launcher':active['launcher'],'production_release':True}))
if __name__=='__main__':main()
